Stack<Long> stack = new Stack<>();
for (int i = 0; i < operand.size(); i++) {
    if (i == 0) {
        stack.push(operand.get(i));
    } else {
        if (op.get(i - 1).equals("+")) {
            stack.push(stack.pop() + operand.get(i));
        } else if (op.get(i - 1).equals("-")) {
            stack.push(stack.pop() - operand.get(i));
        } else if (op.get(i - 1).equals("*")) {
            stack.push(stack.pop() * operand.get(i));
        } else if (op.get(i - 1).equals("//")) {
            stack.push(stack.pop() / operand.get(i));
        } else if (op.get(i - 1).equals("**")) {
            stack.push((long)Math.pow(stack.pop(), operand.get(i)));
        }
    }
}
return stack.pop();

